// Opt-in Windows end-to-end check of mounted CONTENT reads (Batch 9) through the real chain:
//
//   Windows file APIs -> WinFsp -> real hyperdrive-vfs.exe -> real agent (FixtureAgentMain, TEST-ONLY)
//                                                             |-> encrypted chunk cache (Dropbox)
//                                                             '-> FIXTURE provider (generated bytes)
//   This script plays the LOCAL STAND-IN backend (metadata routes) and Electron main (mount, cache
//   session, credential renewal pump). Nothing here touches Google, Dropbox or the real backend:
//   passing it is fixture evidence, NOT live-provider verification.
//
//   cd agent && mvnw -q test-compile && mvnw -q dependency:build-classpath -Dmdep.outputFile=target/fixture-classpath.txt
//   node vfs/tests/content-mount-check.mjs agent vfs/build/hyperdrive-vfs.exe
import { spawn, execFile } from 'node:child_process';
import { createHash, randomBytes } from 'node:crypto';
import { createServer } from 'node:http';
import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
// Async fs on purpose: the stand-in backend runs in THIS process, so blocking calls would stall it.
import { copyFile, mkdir, open, readdir, readFile, rename, stat, unlink, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const agentDir = resolve(process.argv[2] ?? 'agent');
const exe = resolve(process.argv[3] ?? 'vfs/build/hyperdrive-vfs.exe');
const here = dirname(fileURLToPath(import.meta.url));
const results = [];
const evidence = [];
const check = (name, ok, detail = '') => {
  results.push(ok);
  console.log(`${ok ? 'PASS' : 'FAIL'} ${name}${detail ? ` (${detail})` : ''}`);
};
const MiB = 1024 * 1024;
const GiB = 1024 * MiB;

// --- Deterministic fixture content (mirrors FixtureAgentMain.gen) ---
const gen = (seed, p) => {
  const lo = p % 4294967296;
  const hi = Math.floor(p / 4294967296);
  return (lo * 7 + hi * 13 + Math.floor(lo / 2048) + seed) % 256;
};
const expected = (seed, offset, length) => {
  const b = Buffer.allocUnsafe(length);
  for (let i = 0; i < length; i++) b[i] = gen(seed, offset + i);
  return b;
};
const sha = (b) => createHash('sha256').update(b).digest('hex');
const shaOfRange = (seed, offset, length) => {
  const h = createHash('sha256');
  for (let done = 0; done < length; done += 4 * MiB) h.update(expected(seed, offset + done, Math.min(4 * MiB, length - done)));
  return h.digest('hex');
};

const BOX = '11111111-2222-4333-8444-555555555555';
const DRIVE = '66666666-7777-4888-9999-aaaaaaaaaaaa';
const GOOGLE_TOKEN = `fixture-google-${randomBytes(16).toString('hex')}`;
const DROPBOX_TOKEN = `fixture-dropbox-${randomBytes(16).toString('hex')}`;
const FILES = [
  { account: BOX, id: 'id:fixsmall', name: 'small.bin', provider: 'DROPBOX', size: 1_000_003, seed: 1, rev: '0a1b2c3d4e5' },
  { account: BOX, id: 'id:fixcross', name: 'cross.bin', provider: 'DROPBOX', size: 9 * MiB + 123, seed: 2, rev: '1a1b2c3d4e5' },
  { account: BOX, id: 'id:fixbig', name: 'big-5GiB.bin', provider: 'DROPBOX', size: 5 * GiB + 777, seed: 3, rev: '2a1b2c3d4e5' },
  { account: BOX, id: 'id:fixempty', name: 'empty.bin', provider: 'DROPBOX', size: 0, seed: 4, rev: '3a1b2c3d4e5' },
  { account: BOX, id: 'id:fixslow', name: 'slow.bin', provider: 'DROPBOX', size: 100_000, seed: 5, rev: '4a1b2c3d4e5', delayMs: 30_000 },
  { account: DRIVE, id: 'fixgoogle1', name: 'google.bin', provider: 'GOOGLE_DRIVE', size: 6 * MiB + 5, seed: 6, rev: null }
];
const byName = Object.fromEntries(FILES.map((f) => [f.name, f]));

// --- Stand-in backend: grant-scoped metadata routes only ---
const GRANT = `hdm_${randomBytes(32).toString('base64url')}`;
const backendRequests = [];
const backend = createServer((req, res) => {
  const okAuth = req.headers.authorization === `Bearer ${GRANT}`;
  backendRequests.push(`${req.method} ${req.url} ${okAuth ? 'grant-ok' : 'bad-auth'}`);
  const json = (status, body) => res.writeHead(status, { 'content-type': 'application/json' }).end(JSON.stringify(body));
  if (!okAuth) return json(401, { code: 'unauthenticated' });
  const url = new URL(req.url, 'http://127.0.0.1');
  if (url.pathname === '/api/v1/vfs/accounts') {
    return json(200, {
      items: [
        { id: BOX, provider: 'DROPBOX', rootType: 'USER', status: 'CONNECTED' },
        { id: DRIVE, provider: 'GOOGLE_DRIVE', rootType: 'USER', status: 'CONNECTED' }
      ]
    });
  }
  const list = /^\/api\/v1\/vfs\/accounts\/([0-9a-f-]{36})\/files$/.exec(url.pathname);
  if (list) {
    const items = FILES.filter((f) => f.account === list[1]).map((f) => ({
      id: f.id, name: f.name, kind: 'FILE', sizeBytes: f.size, modifiedAt: '2026-11-01T10:00:00Z', directoryLocator: null
    }));
    return json(200, { items, continuation: null });
  }
  const one = /^\/api\/v1\/vfs\/accounts\/([0-9a-f-]{36})\/files\/(.+)$/.exec(url.pathname);
  if (one) {
    const f = FILES.find((x) => x.account === one[1] && x.id === decodeURIComponent(one[2]));
    if (!f) return json(404, { code: 'file_not_found' });
    return json(200, {
      id: f.id, provider: f.provider, kind: 'FILE', sizeBytes: f.size, modifiedAt: '2026-11-01T10:00:00Z',
      providerRevision: f.rev, canDownload: true
    });
  }
  return json(404, { code: 'not_found' });
});
await new Promise((r) => backend.listen(0, '127.0.0.1', r));
const backendOrigin = `http://127.0.0.1:${backend.address().port}`;

// --- Real agent, TEST-ONLY fixture entry point (test classes + runtime classpath) ---
const work = mkdtempSync(join(tmpdir(), 'hd-content-check-'));
const specPath = join(work, 'fixture-spec.json');
writeFileSync(specPath, JSON.stringify({
  googleToken: GOOGLE_TOKEN, dropboxToken: DROPBOX_TOKEN, dropboxRootNamespace: '777',
  files: FILES.map(({ id, provider, size, seed, rev, delayMs }) => ({ id, provider, size, seed, rev, delayMs: delayMs ?? 0 }))
}));
const cpFile = join(agentDir, 'target', 'fixture-classpath.txt');
const classpath = [join(agentDir, 'target', 'classes'), join(agentDir, 'target', 'test-classes'), readFileSync(cpFile, 'utf8').trim()].join(';');
const secret = randomBytes(32).toString('base64url');
const agent = spawn('java', ['-cp', classpath, 'com.hyperdrive.agent.FixtureAgentMain', specPath], { stdio: ['pipe', 'pipe', 'pipe'], windowsHide: true });
agent.stdin.write(`${JSON.stringify({ protocolVersion: 1, secret, dataDir: join(work, 'agent'), logLevel: 'INFO', requestTimeoutMs: 30000 })}\n`);
let agentErr = '';
agent.stderr.on('data', (c) => (agentErr += c));
const agentExited = new Promise((r) => agent.on('exit', r));
const port = await new Promise((r, j) => {
  let out = '';
  agent.stdout.on('data', (c) => {
    out += c;
    const nl = out.indexOf('\n');
    if (nl >= 0) r(JSON.parse(out.slice(0, nl)).port);
  });
  setTimeout(() => j(new Error(`agent handshake timeout: ${agentErr}`)), 30000);
});
const adminRaw = (method, path, body, timeoutMs = 35000) =>
  fetch(`http://127.0.0.1:${port}${path}`, {
    method,
    headers: { Authorization: `Bearer ${secret}`, ...(body ? { 'Content-Type': 'application/json' } : {}) },
    body: body ? JSON.stringify(body) : undefined,
    signal: AbortSignal.timeout(timeoutMs)
  }).then(async (r) => ({ status: r.status, body: await r.json() }));
const admin = (path, body, t) => adminRaw('POST', path, body, t);
const readStats = async () => (await adminRaw('GET', '/local/v1/vfs/status')).body.reads;

// Electron's part, played here: cache key session, mount capability, credential renewal pump.
const USER = '22222222-3333-4444-8555-666666666666';
const cacheSession = await admin('/local/v1/cache/session', { userId: USER, key: randomBytes(32).toString('base64'), fresh: true, budgetBytes: 2 * GiB });
check('agent cache session started (encrypted Dropbox chunks)', cacheSession.status === 200 && cacheSession.body.enabled === true);
const mount = await admin('/local/v1/vfs/mount', { userId: USER, backendOrigin, grant: GRANT, grantExpiresAt: new Date(Date.now() + 600_000).toISOString() });
check('agent issued a mount capability', mount.status === 201 && /^hdv_/.test(mount.body.capability));
let generation = mount.body.generation;
let pumping = true;
const installs = [];
const pump = (async () => {
  while (pumping) {
    let polled;
    try {
      polled = await admin('/local/v1/vfs/credential-requests', { generation }, 30000);
    } catch {
      continue;
    }
    if (polled.status !== 200) {
      await new Promise((r) => setTimeout(r, 200)); // generation ended; a new mount may follow
      continue;
    }
    for (const { accountId } of polled.body.requests) {
      const dropbox = accountId === BOX;
      const r = await admin('/local/v1/vfs/mount/credential', {
        generation, accountId, provider: dropbox ? 'DROPBOX' : 'GOOGLE_DRIVE', accessToken: dropbox ? DROPBOX_TOKEN : GOOGLE_TOKEN,
        providerExpiresAt: new Date(Date.now() + 3600_000).toISOString(), ...(dropbox ? { rootNamespaceId: '777' } : {})
      });
      installs.push(`${accountId}:${r.status}`);
    }
  }
})();

// --- Real VFS, normal mode ---
const letter = [...'ZYXWVUTSRQPONMLKJI'].find((l) => !existsSync(`${l}:\\`));
let vfsErr = '';
function startVfs(capability) {
  const proc = spawn(exe, [], { stdio: ['pipe', 'pipe', 'pipe'], windowsHide: true });
  const run = { proc, events: [], exitAt: null };
  proc.stderr.on('data', (c) => (vfsErr += c));
  run.exited = new Promise((r) => proc.on('exit', (code) => { run.exitAt = Date.now(); r(code); }));
  let buf = '';
  run.mounted = new Promise((r, j) => {
    proc.stdout.on('data', (c) => {
      buf += c;
      let nl;
      while ((nl = buf.indexOf('\n')) >= 0) {
        const e = JSON.parse(buf.slice(0, nl));
        buf = buf.slice(nl + 1);
        run.events.push(e);
        if (e.event === 'started') proc.stdin.write(`${JSON.stringify({ protocolVersion: 1, agentPort: port, capability, mount: { driveLetter: letter } })}\n`);
        if (e.event === 'mounted') r();
        if (e.event === 'failed') j(new Error(e.code));
      }
    });
    setTimeout(() => j(new Error('mount timeout')), 30000);
  });
  return run;
}
const first = startVfs(mount.body.capability);
await first.mounted;
const vfs = first.proc;
const events = first.events;
const exited = first.exited;
check('real mount through the agent', events.map((e) => e.event).join(',') === 'started,agent-authenticated,volume-created,mounted');

const root = (await readdir(`${letter}:\\`)).sort();
check('root lists both fixture accounts', root.length === 2 && /^Dropbox - Personal \[[0-9a-f]{8}\]$/.test(root[0]) && /^Google Drive - Personal \[[0-9a-f]{8}\]$/.test(root[1]), root.join('|'));
const boxDir = `${letter}:\\${root[0]}`;
const driveDir = `${letter}:\\${root[1]}`;
const p = (f) => `${f.account === BOX ? boxDir : driveDir}\\${f.name}`;
check('directory listing through the agent', (await readdir(boxDir)).sort().join('|') === 'big-5GiB.bin|cross.bin|empty.bin|slow.bin|small.bin');
check('> 4 GiB size reported exactly', (await stat(p(byName['big-5GiB.bin']))).size === 5 * GiB + 777);

// 1. Full read + copy of a small file, SHA-256.
const small = byName['small.bin'];
const smallSha = sha(expected(small.seed, 0, small.size));
const whole = await readFile(p(small));
check('full read of a small file matches SHA-256', whole.length === small.size && sha(whole) === smallSha, `${whole.length} bytes`);
const copyTarget = join(work, 'small-copy.bin');
await copyFile(p(small), copyTarget);
check('CopyFile out of the drive matches SHA-256', sha(await readFile(copyTarget)) === smallSha);
const attrs = await new Promise((r) => execFile('powershell', ['-NoProfile', '-Command', `(Get-Item -LiteralPath '${copyTarget}').Attributes.ToString()`], (e, out) => r(e ? 'unknown' : out.trim())));
evidence.push(`copied file attributes on the local disk: ${attrs}`);

// 2. Nonzero offsets and cross-chunk reads (buffered handle reads, position given).
const cross = byName['cross.bin'];
const fh = await open(p(cross), 'r');
const at = async (h, offset, length) => {
  const b = Buffer.alloc(length);
  const { bytesRead } = await h.read(b, 0, length, offset);
  return b.subarray(0, bytesRead);
};
check('cross-chunk read at 4 MiB - 100', (await at(fh, 4 * MiB - 100, 300)).equals(expected(cross.seed, 4 * MiB - 100, 300)));
let randomOk = true;
for (let i = 0; i < 25; i++) {
  const off = Math.floor(Math.random() * cross.size);
  const len = 1 + Math.floor(Math.random() * 200_000);
  const want = Math.min(len, cross.size - off);
  if (!(await at(fh, off, len)).equals(expected(cross.seed, off, want))) randomOk = false;
}
check('25 random-offset reads are exact', randomOk);
check('final partial read returns only the remaining bytes', (await at(fh, cross.size - 10, 100)).equals(expected(cross.seed, cross.size - 10, 10)));
check('read at EOF returns 0 bytes', (await at(fh, cross.size, 100)).length === 0);
await fh.close();

// 3. > 4 GiB file: 64-bit offsets, across 2^32, at the very end.
const big = byName['big-5GiB.bin'];
const bh = await open(p(big), 'r');
check('read across the 4 GiB (2^32) boundary', (await at(bh, 4 * GiB - 1000, 2 * MiB)).equals(expected(big.seed, 4 * GiB - 1000, 2 * MiB)));
check('read beyond 4 GiB crossing a chunk boundary', (await at(bh, 4 * GiB + 4 * MiB - 7, 100)).equals(expected(big.seed, 4 * GiB + 4 * MiB - 7, 100)));
check('last 10 bytes of a 5 GiB file', (await at(bh, big.size - 10, 100)).equals(expected(big.seed, big.size - 10, 10)));
check('EOF of a 5 GiB file', (await at(bh, big.size, 10)).length === 0);

// 4. Concurrent readers on the large file.
const offsets = [0, 1 * GiB + 3, 2 * GiB + 5, 3 * GiB + 7, 4 * GiB + 11, 5 * GiB - 3 * MiB];
const concurrent = await Promise.all(offsets.map(async (o) => {
  const h = await open(p(big), 'r');
  try {
    return (await at(h, o, 3 * MiB)).equals(expected(big.seed, o, 3 * MiB));
  } finally {
    await h.close();
  }
}));
check('6 concurrent readers (separate handles) get exact bytes', concurrent.every(Boolean));
await bh.close();

// 5. Non-cached (FILE_FLAG_NO_BUFFERING) reads reach the VFS as one large callback -> split into 4 MiB agent reads.
const unbuffered = (path, offset, length) => new Promise((r) => execFile('powershell', ['-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', join(here, 'unbuffered-read.ps1'), '-Path', path, '-Offset', String(offset), '-Length', String(length)], { timeout: 120_000 }, (e, out) => {
  try { r(JSON.parse(out.trim().split(/\r?\n/).pop())); } catch { r({ ok: false, error: e?.message ?? 'no output' }); }
}));
let before = await readStats();
const u1 = await unbuffered(p(big), 4 * GiB, 12 * MiB);
let after = await readStats();
check('12 MiB non-cached read at 4 GiB is exact', u1.ok && u1.bytes === 12 * MiB && u1.sha256 === shaOfRange(big.seed, 4 * GiB, 12 * MiB), JSON.stringify(u1).slice(0, 80));
check('...and reached the agent as >= 3 bounded (<= 4 MiB) reads', after.reads - before.reads >= 3, `${after.reads - before.reads} agent reads`);
const endOffset = Math.floor((big.size - 1) / 4096) * 4096;
const u2 = await unbuffered(p(big), endOffset, 8192);
check('non-cached read at the end returns only the real bytes', u2.ok && u2.bytes === big.size - endOffset && u2.sha256 === shaOfRange(big.seed, endOffset, big.size - endOffset), JSON.stringify(u2).slice(0, 80));
const u3 = await unbuffered(p(big), 6 * GiB, 4096);
check('non-cached read beyond EOF: 0 bytes or EOF error, never data', (u3.ok && u3.bytes === 0) || u3.error === 38, JSON.stringify(u3));

// 6. Cache: Dropbox chunks are served by the agent's encrypted cache; Google always bypasses it.
//    Deltas are lower bounds: other readers on the machine (e.g. real-time antivirus scanning a file
//    when it is opened) may add agent reads of their own; the evidence lines show the extra bytes.
before = await readStats();
const c1 = await unbuffered(p(small), 0, 512 * 1024);
after = await readStats();
check('Dropbox re-read (non-cached in Windows) is answered from the agent cache', c1.ok && c1.sha256 === shaOfRange(small.seed, 0, 512 * 1024) && after.cacheBytes - before.cacheBytes >= 512 * 1024 && after.providerBytes === before.providerBytes, `cache +${after.cacheBytes - before.cacheBytes}, provider +${after.providerBytes - before.providerBytes}`);
const google = byName['google.bin'];
const g = await readFile(p(google));
evidence.push(`Dropbox non-cached re-read of 524288 bytes: agent cache +${after.cacheBytes - before.cacheBytes}, provider +${after.providerBytes - before.providerBytes}`);
check('Google file full read matches SHA-256', sha(g) === shaOfRange(google.seed, 0, google.size));
before = await readStats();
const g2 = await unbuffered(p(google), 0, 1024 * 1024);
after = await readStats();
check('Google re-read goes to the provider again (cache bypass)', g2.ok && after.providerBytes - before.providerBytes >= 1024 * 1024 && after.cacheBytes === before.cacheBytes, `provider +${after.providerBytes - before.providerBytes}`);
evidence.push(`Google non-cached re-read of 1048576 bytes: provider +${after.providerBytes - before.providerBytes}, cache +${after.cacheBytes - before.cacheBytes}`);
check('credential renewal installed one credential per account', installs.length === 2 && installs.every((s) => s.endsWith(':201')), installs.join(','));

// 7. Empty file and read-only enforcement.
check('zero-byte file reads as empty', (await readFile(p(byName['empty.bin']))).length === 0);
const rejects = async (fn) => { try { await fn(); return false; } catch { return true; } };
check('creating a file is rejected', await rejects(() => writeFile(`${boxDir}\\new.txt`, 'x')));
check('opening a file for writing is rejected', await rejects(async () => (await open(p(small), 'r+')).close()));
check('deleting a file is rejected', await rejects(() => unlink(p(small))));
check('renaming a file is rejected', await rejects(() => rename(p(small), `${boxDir}\\renamed.bin`)));
check('creating a folder is rejected', await rejects(() => mkdir(`${boxDir}\\dir`)));
check('content unchanged after write attempts', sha(await readFile(p(small))) === smallSha);

const stats = await readStats();
evidence.push(`agent counters: ${JSON.stringify({ reads: stats.reads, bytesReturned: stats.bytesReturned, providerBytes: stats.providerBytes, cacheBytes: stats.cacheBytes, opens: stats.opens, failures: stats.failures })}`);

// 8. Unmount with an outstanding read (the fixture provider holds slow.bin for 30 s).
const slowRead = readFile(p(byName['slow.bin'])).then(() => 'resolved', (e) => `rejected:${e.code}`);
await new Promise((r) => setTimeout(r, 1500));
const unmountAt = Date.now();
vfs.stdin.write('unmount\n');
const exitCode = await Promise.race([exited, new Promise((r) => setTimeout(() => r('timeout'), 20000))]);
const slowOutcome = await Promise.race([slowRead, new Promise((r) => setTimeout(() => r('still-pending'), 20000))]);
check('unmount with an outstanding read completes in bounded time', exitCode !== 'timeout' && first.exitAt - unmountAt < 15000, `${first.exitAt ? first.exitAt - unmountAt : '?'} ms, exit ${exitCode}`);
check('the outstanding read failed instead of returning data', slowOutcome.startsWith('rejected'), slowOutcome);
check('VFS reported unmounted', events.some((e) => e.event === 'unmounted' && e.reason === 'requested'));
check('drive letter released', !existsSync(`${letter}:\\`));

// 9. No secrets anywhere in VFS events/diagnostics or agent logs.
const out = JSON.stringify(events) + vfsErr;
check('VFS output has no capability, tokens or grant', ![mount.body.capability, GOOGLE_TOKEN, DROPBOX_TOKEN, GRANT, 'hdf_'].some((s) => out.includes(s)));
check('agent log has no capability, tokens, grant or read handles', ![mount.body.capability, GOOGLE_TOKEN, DROPBOX_TOKEN, GRANT, 'hdf_', 'hdh_'].some((s) => agentErr.includes(s)));
check('backend saw only grant-authenticated VFS metadata routes', backendRequests.every((r) => r.endsWith('grant-ok') && r.includes(' /api/v1/vfs/')), `${backendRequests.length} requests`);

// 10. VFS process crash: a new mount generation, then the VFS process is killed while mounted.
const remount = async () => {
  const m = await admin('/local/v1/vfs/mount', { userId: USER, backendOrigin, grant: GRANT, grantExpiresAt: new Date(Date.now() + 600_000).toISOString() });
  generation = m.body.generation;
  const run = startVfs(m.body.capability);
  await run.mounted;
  return run;
};
const second = await remount();
check('a new mount generation reads content again', sha(await readFile(p(small))) === smallSha, `generation ${generation}`);
second.proc.kill();
await second.exited;
let released = false;
for (let i = 0; i < 50 && !released; i++) {
  released = !existsSync(`${letter}:\\`);
  if (!released) await new Promise((r) => setTimeout(r, 100));
}
check('killing the VFS process removes the drive (WinFsp/Windows cleanup)', released);

// 11. Agent crash with an outstanding read: the read fails, the VFS unmounts itself (heartbeat).
const third = await remount();
const crashRead = readFile(p(byName['slow.bin'])).then(() => 'resolved', (e) => `rejected:${e.code}`);
await new Promise((r) => setTimeout(r, 1500));
pumping = false;
const killedAt = Date.now();
agent.kill();
const crashOutcome = await Promise.race([crashRead, new Promise((r) => setTimeout(() => r('still-pending'), 20000))]);
const readEndedAfter = Date.now() - killedAt;
check('agent crash: the outstanding read fails quickly instead of hanging', crashOutcome.startsWith('rejected'), `${crashOutcome} after ${readEndedAfter} ms`);
const selfUnmount = await Promise.race([third.exited, new Promise((r) => setTimeout(() => r('timeout'), 45000))]);
check('agent crash: the VFS unmounts itself (agent-unreachable)', selfUnmount !== 'timeout' && third.events.some((e) => e.event === 'unmounted' && e.reason === 'agent-unreachable'), `${third.exitAt ? third.exitAt - killedAt : '?'} ms`);
check('agent crash: drive letter released', !existsSync(`${letter}:\\`));
await agentExited; // already exited after kill(); never wait for an event that has fired
await pump.catch(() => undefined);
backend.close();
rmSync(work, { recursive: true, force: true });
for (const e of evidence) console.log(`INFO ${e}`);
const failed = results.filter((ok) => !ok).length;
console.log(`${results.length} checks, ${failed} failed (drive ${letter}:) -- FIXTURE provider, not live Google/Dropbox`);
process.exit(failed === 0 ? 0 : 1);
